const STORAGE_KEY = "koraRegisteredUserV3";
const AUTH_VERSION = "kora-auth-v3";
const IDEAS_KEY = "koraIdeasV1";
const SELECTION_TEXT = {
  en:{selectionNoRight:"There is no right or wrong choice. Choose the character that feels like you.",selectionPickOne:"Choose one of the 10 characters.",selectionConfirm:"THIS IS MY CHARACTER →",selectionChosen:"SELECTED CHARACTER",selectionHint:"This is the strength you want to carry into your KORA journey."},
  tr:{selectionNoRight:"Doğru ya da yanlış seçim yok. Kendine en yakın hissettiğin karakteri seç.",selectionPickOne:"10 karakterden birini seç.",selectionConfirm:"BU BENİM KARAKTERİM →",selectionChosen:"SEÇİLEN KARAKTER",selectionHint:"Bu, KORA yolculuğunda yanında taşıyacağın güç."},
  de:{selectionNoRight:"Es gibt keine richtige oder falsche Wahl. Wähle den Charakter, der sich nach dir anfühlt.",selectionPickOne:"Wähle einen der 10 Charaktere.",selectionConfirm:"DAS IST MEIN CHARAKTER →",selectionChosen:"GEWÄHLTER CHARAKTER",selectionHint:"Diese Kraft nimmst du mit auf deine KORA-Reise."},
  fr:{selectionNoRight:"Il n'y a pas de bon ou de mauvais choix. Choisis le personnage qui te ressemble.",selectionPickOne:"Choisis l'un des 10 personnages.",selectionConfirm:"C'EST MON PERSONNAGE →",selectionChosen:"PERSONNAGE CHOISI",selectionHint:"C'est la force que tu emporteras dans ton voyage KORA."},
  es:{selectionNoRight:"No hay una elección correcta o incorrecta. Elige el personaje que sientas cercano.",selectionPickOne:"Elige uno de los 10 personajes.",selectionConfirm:"ESTE ES MI PERSONAJE →",selectionChosen:"PERSONAJE ELEGIDO",selectionHint:"Esta es la fuerza que llevarás en tu viaje por KORA."},
  it:{selectionNoRight:"Non esiste una scelta giusta o sbagliata. Scegli il personaggio che senti vicino.",selectionPickOne:"Scegli uno dei 10 personaggi.",selectionConfirm:"QUESTO È IL MIO PERSONAGGIO →",selectionChosen:"PERSONAGGIO SCELTO",selectionHint:"Questa è la forza che porterai nel tuo viaggio KORA."}
};
Object.keys(TRANSLATIONS).forEach(k=>Object.assign(TRANSLATIONS[k],SELECTION_TEXT[k]||SELECTION_TEXT.en));
let selectedCharacterIndex = null;
let lang = "en";
let currentMission = 1;
let attemptCount = 0;

const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
function data() { return TRANSLATIONS[lang] || TRANSLATIONS.en; }
function profile() {
  try {
    const p = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
    // HARD LOCK: only an explicit v3 registration can unlock character selection/chat.
    if (!p || p.authVersion !== AUTH_VERSION || p.registered !== true || !p.name || (!p.email && !p.phone)) return null;
    if (!Array.isArray(p.progress) || p.progress.length !== CHARACTERS.length) return null;
    if (!(p.character === null || (Number.isInteger(p.character) && p.character >= 0 && p.character < CHARACTERS.length))) return null;
    return p;
  } catch {
    return null;
  }
}
function saveProfile(p) { localStorage.setItem(STORAGE_KEY, JSON.stringify(p)); }
function showDialog(id) { const d=$("#"+id); if(d && !d.open) d.showModal(); }
function closeDialog(id) { const d=$("#"+id); if(d && d.open) d.close(); }

function applyLanguage(next) {
  lang = TRANSLATIONS[next] ? next : "en";
  const d = data();
  document.documentElement.lang = lang;
  $("#languageSelect").value = lang;
  $$("[data-i18n]").forEach(el => {
    const key=el.dataset.i18n;
    if(d[key] !== undefined) el.textContent=d[key];
  });
  $$("[data-i18n-placeholder]").forEach(el => {
    const key=el.dataset.i18nPlaceholder;
    if(d[key] !== undefined) el.placeholder=d[key];
  });
  document.title = lang==="en" ? "KORA Universe — Discover Yourself" : (lang==="tr" ? "KORA Universe — Kendini Keşfet" : "KORA Universe");
  renderCharacters();
  renderStory();
  renderDiscover();
  renderProfile();
  renderCharacterChooser();
  renderIdeas();
  refreshMission();
}

function renderCharacters() {
  const d=data(), grid=$("#characterGrid");
  grid.innerHTML="";
  CHARACTERS.forEach((c,i)=>{
    const card=document.createElement("article");
    card.className="character-card";
    card.innerHTML=`<div class="character-code">0${i+1}</div>
      <button class="pick-mini" data-pick="${i}">+</button>
      <div class="character-main">
        <img class="character-thumb" src="images/${c[1]}" alt="${c[0]}">
        <div><div class="character-name">${c[0]}</div><div class="character-role">${d.roles[i]}</div></div>
      </div>
      <div class="character-power">${d.powers[i]}</div>`;
    card.querySelector(".pick-mini").addEventListener("click",e=>{e.stopPropagation();selectCharacter(i);});
    card.addEventListener("click",()=>selectCharacter(i));
    grid.appendChild(card);
  });
}

function renderCharacterChooser() {
  const d=data(), box=$("#characterChooser");
  box.innerHTML="";
  CHARACTERS.forEach((c,i)=>{
    const b=document.createElement("button");
    b.className="chooser-card"+(selectedCharacterIndex===i?" selected":"");
    b.innerHTML=`<img src="images/${c[1]}" alt="${c[0]}"><div><strong>${c[0]}</strong><span>${d.roles[i]}</span><span>${d.powers[i]}</span></div>`;
    b.addEventListener("click",()=>previewCharacter(i));
    box.appendChild(b);
  });
  renderSelectionPreview();
}

function previewCharacter(index) {
  if(!Number.isInteger(index) || !CHARACTERS[index]) return;
  selectedCharacterIndex=index;
  const box=$("#selectionPreview");
  const d=data(), c=CHARACTERS[index];
  if(box){
    box.innerHTML=`<div class="selection-preview-card"><img src="images/${c[1]}" alt="${c[0]}"><div><span class="selection-badge">${d.selectionChosen}</span><h3>${c[0]}</h3><p>${d.roles[index]}</p><p>${d.powers[index]}</p><p>${d.selectionHint}</p></div></div>`;
  }
  const confirm=$("#confirmCharacter");
  if(confirm){
    confirm.removeAttribute("disabled");
    confirm.setAttribute("aria-disabled","false");
    confirm.dataset.selectedCharacter=String(index);
    confirm.textContent=d.selectionConfirm;
  }
  $$("#characterChooser .chooser-card").forEach((el,i)=>el.classList.toggle("selected",i===index));
}

function renderSelectionPreview() {
  const d=data(), box=$("#selectionPreview"), confirm=$("#confirmCharacter");
  if(selectedCharacterIndex===null){
    box.innerHTML=`<div class="selection-placeholder"><span class="selection-placeholder-icon">✦</span><strong>${d.selectionPickOne}</strong></div>`;
    confirm.removeAttribute("disabled");
    confirm.setAttribute("aria-disabled","true");
    delete confirm.dataset.selectedCharacter;
    confirm.textContent=d.selectionConfirm;
    return;
  }
  const c=CHARACTERS[selectedCharacterIndex];
  box.innerHTML=`<div class="selection-preview-card"><img src="images/${c[1]}" alt="${c[0]}"><div><span class="selection-badge">${d.selectionChosen}</span><h3>${c[0]}</h3><p>${d.roles[selectedCharacterIndex]}</p><p>${d.powers[selectedCharacterIndex]}</p><p>${d.selectionHint}</p></div></div>`;
  confirm.removeAttribute("disabled");
  confirm.setAttribute("aria-disabled","false");
  confirm.dataset.selectedCharacter=String(selectedCharacterIndex);
  confirm.textContent=d.selectionConfirm;
}

function renderStory() {
  const d=data(), grid=$("#storyGrid");
  grid.innerHTML="";
  const storyImages=["kora.png","nyx.png","kora-group.png","vael.png","orin.png","cryx.png"];
  d.chapters.forEach((x,i)=>{
    const el=document.createElement("article");
    el.className="chapter-card";
    el.style.backgroundImage=`linear-gradient(180deg, rgba(7,8,13,.08) 0%, rgba(7,8,13,.70) 46%, rgba(7,8,13,.97) 100%), url("images/${storyImages[i]}")`;
    el.innerHTML=`<div class="chapter-image" aria-hidden="true"></div><div class="chapter-content"><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><button class="chapter-open" type="button">${lang === "tr" ? "HİKÂYEYE GİR →" : lang === "de" ? "GESCHICHTE ÖFFNEN →" : lang === "fr" ? "OUVRIR L'HISTOIRE →" : lang === "es" ? "ABRIR HISTORIA →" : lang === "it" ? "APRI LA STORIA →" : "ENTER STORY →"}</button></div>`;
    el.querySelector('.chapter-open').addEventListener('click',()=>openStoryChapter(i));
    grid.appendChild(el);
  });
}

function openStoryChapter(i) {
  const d=data(), x=d.chapters[i];
  const intro={
    en:["The first chapter is waiting to be discovered.","The story content will be expanded here scene by scene."],
    tr:["İlk bölüm keşfedilmeyi bekliyor.","Hikâyenin içeriği burada sahne sahne genişletilecek."],
    de:["Das erste Kapitel wartet darauf, entdeckt zu werden.","Die Geschichte wird hier Szene für Szene erweitert."],
    fr:["Le premier chapitre attend d'être découvert.","L'histoire sera développée ici scène par scène."],
    es:["El primer capítulo espera ser descubierto.","La historia se ampliará aquí escena por escena."],
    it:["Il primo capitolo aspetta di essere scoperto.","La storia sarà ampliata qui scena dopo scena."]
  }[lang] || ["The first chapter is waiting to be discovered.","The story content will be expanded here scene by scene."];
  $("#discoverContent").innerHTML=`<p class="eyebrow">${x[0]}</p><h2 class="discover-detail-title">${x[1]}</h2><p class="discover-detail-text">${x[2]}</p><p class="discover-detail-text">${intro[0]}<br>${intro[1]}</p>`;
  showDialog("discoverDialog");
}

function renderDiscover() {
  const d=data(), grid=$("#discoverGrid");
  grid.innerHTML="";
  d.discover.forEach((x,i)=>{
    const el=document.createElement("article");
    el.className="discover-card";
    el.innerHTML=`<div class="discover-number">0${i+1}</div><div class="discover-card-icon">${["✦","◈","▣","◇","◎","◉"][i]}</div><h3>${x[0]}</h3><p>${x[1]}</p><span class="discover-link">${d.explore}</span>`;
    el.addEventListener("click",()=>openDiscovery(i));
    grid.appendChild(el);
  });
}

function openDiscovery(i) {
  const d=data(), x=d.discover[i];
  $("#discoverContent").innerHTML=`<p class="eyebrow">0${i+1}</p><h2 class="discover-detail-title">${x[2]}</h2><p class="discover-detail-text">${x[3]}</p><ul class="dialog-list">${x[4].map(v=>`<li>${v}</li>`).join("")}</ul>`;
  showDialog("discoverDialog");
}

function selectCharacter(index, fromChooser=false) {
  if(!Number.isInteger(index) || !CHARACTERS[index]) return;
  const p = profile();
  if(!p) {
    closeDialog("characterDialog");
    openAuth("register");
    return;
  }

  // Registered user: save the character and start chat immediately.
  p.character = index;
  if(!Array.isArray(p.progress)) p.progress = Array(10).fill(0);
  saveProfile(p);
  currentMission = Math.min((p.progress[index]||0)+1,100);
  attemptCount = 0;
  selectedCharacterIndex = index;
  renderProfile();
  closeDialog("characterDialog");
  openChat(index);
}

function openCharacterChooser() {
  const p = profile();
  if (!p) {
    // NO CHARACTER SELECTION before registration/login.
    openAuth("register");
    return;
  }
  selectedCharacterIndex = (Number.isInteger(p.character)) ? p.character : null;
  renderCharacterChooser();
  showDialog("characterDialog");
}

function addChat(type,text){
  const box=$("#chatMessages");
  if(!box) return;
  const wrap=document.createElement("div");
  wrap.className="msg "+(type==="user"?"user":"character");
  wrap.innerHTML=String(text ?? "").replace(/\n/g,"<br>");
  box.appendChild(wrap);
  box.scrollTop=box.scrollHeight;
}

function openChat(index) {
  const p = profile();
  if (!p) {
    // NO CHAT before registration/login.
    openAuth("register");
    return;
  }
  const d=data(), c=CHARACTERS[index];
  $("#chatImage").src="images/"+c[1]; $("#chatImage").alt=c[0];
  $("#chatName").textContent=c[0]; $("#chatRole").textContent=d.roles[index];
  $("#chatMessages").innerHTML="";
  chatReplyHistory[index]=[];
  const savedTurns=memoryTurns(index);
  if(savedTurns.length){
    savedTurns.slice(-6).forEach(t=>{ addChat("user",t.user); addChat("character",t.assistant); });
    addChat("character", lang==="tr" ? "Tekrar buradasın. Önceki konuşmamızdaki konuyu hatırlıyorum; devam edelim." : "You’re back. I remember our previous topic. Let’s continue.");
  }else{
    addChat("character", initialCharacterMessage(index));
  }
  const signal=getDailySignal(index);
  const today=dateKey();
  const dailyMem=chatMemoryLoad();
  const dailyForChar=(dailyMem.__daily||{})[String(index)];
  if(dailyForChar!==today){
    addChat("character",lang==="tr"?`BUGÜNÜN GÜCÜ: ${signal.message}\nBUGÜNÜN GÖREVİ: ${signal.task}`:`TODAY'S SIGNAL: ${signal.message}\nTODAY'S CHALLENGE: ${signal.task}`);
    const next=dailyMem.__daily||{};next[String(index)]=today;dailyMem.__daily=next;chatMemorySave(dailyMem);
  }
  showDialog("chatDialog");
}

