const CANON_PREFIX = {
  tr:"KORA kanonunda şu anda kesin olarak tanımlanan bilgiyi aşmadan konuşacağım. Tanımlanmamış bir kristal, dünya, olay veya karakter ayrıntısını uydurmayacağım.",
  en:"I will stay within the KORA canon defined so far. I will not invent an undefined crystal, world, event, or character detail.",
  de:"Ich bleibe innerhalb der bisher definierten KORA-Lore und erfinde keine nicht festgelegten Details.",
  fr:"Je reste dans le canon de KORA défini jusqu’ici et je n’invente pas les éléments non établis.",
  es:"Me mantendré dentro del canon de KORA definido hasta ahora y no inventaré detalles no establecidos.",
  it:"Rimarrò nel canone di KORA definito finora e non inventerò dettagli non stabiliti."
};

function chatMemoryLoad(){
  try{return JSON.parse(localStorage.getItem(CHAT_MEMORY_KEY)||"{}")}catch{return {}}
}
function chatMemorySave(mem){localStorage.setItem(CHAT_MEMORY_KEY,JSON.stringify(mem))}
function rememberTurn(index,user,assistant){
  const mem=chatMemoryLoad();
  if(!Array.isArray(mem[index])) mem[index]=[];
  mem[index].push({user:String(user).slice(0,500),assistant:String(assistant).slice(0,1200),ts:Date.now()});
  mem[index]=mem[index].slice(-20);
  chatMemorySave(mem);
}
function memoryTurns(index){return chatMemoryLoad()[index]||[]}
function priorTopics(index){
  const turns=memoryTurns(index).slice(-5);
  return turns.map(x=>x.user).filter(Boolean).slice(-3);
}
function noRepeat(index,pool){
  if(!chatReplyHistory[index]) chatReplyHistory[index]=[];
  const used=chatReplyHistory[index];
  let p=pool.filter(Boolean).filter(x=>!used.includes(x));
  if(!p.length){used.length=0;p=pool.filter(Boolean)}
  const r=p[Math.floor(Math.random()*p.length)] || "";
  used.push(r); if(used.length>10) used.shift();
  return r;
}
function chatIntent(msg){
  const m=msg.toLocaleLowerCase("tr-TR");
  if(/^(merhaba|selam|hey|hello|hi|günaydın|iyi akşamlar)/.test(m)) return "greeting";
  if(/teşekkür|sağol|saol|eyvallah|thanks|thank you/.test(m)) return "thanks";
  if(/neden|niye|sebep|why|reason/.test(m)) return "why";
  if(/nasıl|nasil|how|yapılır|yapilir|yardım|yardim|help|çöz|coz|öner|oner/.test(m)) return "help";
  if(/ne biliyorsun|bilgi|anlat|nedir|what is|explain|what do you know/.test(m)) return "knowledge";
  if(/kristal|dünya|dunyalar|the witness|witness|kanon|canon|kora evreni/.test(m)) return "canon";
  if(/güç|guç|kuvvet|enerji|yetenek|power/.test(m)) return "power";
  if(/denge|karar|seçim|secim|öncelik|oncelik/.test(m)) return "decision";
  if(/üzgün|uzgun|korku|kaygı|kaygi|stres|yalnız|yalniz|moral|duygu/.test(m)) return "support";
  return "default";
}
function lookupGeneral(msg){
  const m=" "+msg.toLocaleLowerCase("tr-TR")+" ";
  for(const item of GENERAL_KNOWLEDGE){
    if(item[0].some(k=>m.includes(k))) return item[1][lang]||item[1].en;
  }
  return "";
}
function lookupCharacterKnowledge(name,msg){
  const m=msg.toLocaleLowerCase("tr-TR");
  for(const item of (CHARACTER_KNOWLEDGE[name]||[])){
    if(item[0].some(k=>m.includes(k))) {
      const value=item[1];
      if(value && typeof value === "object") return value[lang] || value.en || value.tr || "";
      return value || "";
    }
  }
  return "";
}
function canonReply(index){
  const d=data(), name=CHARACTERS[index][0];
  return (CANON_PREFIX[lang]||CANON_PREFIX.en)+" "+(
    lang==="tr"
      ? `Benim şu an tanımlı kimliğim: ${name} — ${d.roles[index]}; güç alanım: ${d.powers[index]}.`
      : `My currently defined identity is ${name} — ${d.roles[index]}; my power area is ${d.powers[index]}.`
  );
}
function contextualBridge(index){
  const topics=priorTopics(index);
  if(!topics.length) return "";
  const topic=topics[topics.length-1].slice(0,90);
  const b={
    tr:` Önceki mesajındaki “${topic}” konusunu da aklımda tutuyorum.`,
    en:` I’m also keeping your earlier point “${topic}” in mind.`
  }[lang];
  return b||"";
}
function getDynamicCharacterReply(index,msg){
  const name=CHARACTERS[index][0];
  const intent=chatIntent(msg);
  if(intent==="canon") return canonReply(index);

  const specific=lookupCharacterKnowledge(name,msg);
  if(specific) return specific+contextualBridge(index);

  const general=lookupGeneral(msg);
  if(general) return general+contextualBridge(index);

  const pack=(CHARACTER_CHAT[name]?.[lang]||CHARACTER_CHAT[name]?.en);
  if(!pack) return lang==="tr"?"Seni dinliyorum.":"I’m listening.";

  if(intent==="greeting"){
    return noRepeat(index,[...(pack.intro||[]),lang==="tr"?"Buradayım. Aklındaki şeyi doğrudan anlat.":"I’m here. Tell me what is on your mind."]);
  }
  if(intent==="thanks"){
    return noRepeat(index,[...(pack.default||[]),lang==="tr"?"Rica ederim. Şimdi bunu senin durumuna uygulayalım.":"You’re welcome. Now let’s apply it to your situation."]);
  }

  const pool=[...(pack[intent]||[]),...(pack.default||[])];
  let r=noRepeat(index,pool);
  const follow={
    tr:[
      "Bunu bir örnekle açmamı istersen, kendi durumundan bir ayrıntı ver.",
      "Şimdi bir sonraki adımı senin durumuna göre netleştirebiliriz.",
      "Bunun hangi kısmı senin için en zor olanı?"
    ],
    en:[
      "Give me one detail from your situation and I can make this concrete.",
      "We can turn that into a specific next step.",
      "Which part of this is hardest for you?"
    ]
  }[lang]||[];
  if(follow.length) r += " " + noRepeat(index,follow);
  return r+contextualBridge(index);
}
function characterReply(index,msg){
  const clean=String(msg||"").trim().replace(/\s+/g," ").slice(0,500);
  return clean ? getDynamicCharacterReply(index,clean) : (lang==="tr"?"Seni dinliyorum.":"I’m listening.");
}


