function dailyStateLoad(){try{return JSON.parse(localStorage.getItem(DAILY_MOTIVATION_KEY)||"{}")}catch{return {}}}
function dailyStateSave(v){localStorage.setItem(DAILY_MOTIVATION_KEY,JSON.stringify(v))}
function dateKey(){
  const d=new Date();
  const y=d.getFullYear();
  const m=String(d.getMonth()+1).padStart(2,"0");
  const day=String(d.getDate()).padStart(2,"0");
  return `${y}-${m}-${day}`;
}

function localDayNumber(){
  const d=new Date();
  const localMidnight=new Date(d.getFullYear(),d.getMonth(),d.getDate());
  return Math.floor(localMidnight.getTime()/86400000);
}

