function buildDailyLibrary(name, language){
  const p=DAILY_GENERATOR[name]||DAILY_GENERATOR.KORA; const x=p[language]||p.tr;
  const out=[];
  for(let i=0;i<x.open.length;i++){
    for(let j=0;j<x.core.length;j++){
      for(let k=0;k<x.close.length;k++) out.push(`${x.open[i]}, ${x.core[j]}. ${x.close[k]}`);
    }
  }
  return out; // 12*12*3 = 432
}
