function missionStateLoad(){try{return JSON.parse(localStorage.getItem(MISSION_STATE_KEY)||"{}")}catch{return {}}}
function missionStateSave(v){localStorage.setItem(MISSION_STATE_KEY,JSON.stringify(v))}
function missionDifficulty(level){
  if(level<=10)return {name:lang==="tr"?"KAŞİF":"EXPLORER",stages:1,options:3};
  if(level<=30)return {name:lang==="tr"?"YOL BULUCU":"PATHFINDER",stages:2,options:3};
  if(level<=50)return {name:lang==="tr"?"STRATEJİST":"STRATEGIST",stages:2,options:4};
  if(level<=70)return {name:lang==="tr"?"MÜCADELECİ":"CHALLENGER",stages:3,options:4};
  if(level<=90)return {name:lang==="tr"?"USTALIK":"MASTERY",stages:4,options:4};
  if(level<100)return {name:lang==="tr"?"MUHAFIZ":"GUARDIAN",stages:4,options:5};
  if(level===100)return {name:lang==="tr"?"SON KAPI":"FINAL GATE",stages:5,options:5};
  const tier=Math.min(3,Math.floor((level-101)/25));
  return {name:lang==="tr"?"USTALIK+":"MASTERY+",stages:5+tier,options:5+(tier>=2?1:0)};
}
function seededOrder(seed,length){const arr=[...Array(length).keys()];let x=Math.abs(seed|0)+1;for(let i=length-1;i>0;i--){x=(x*1664525+1013904223)>>>0;const j=x%(i+1);[arr[i],arr[j]]=[arr[j],arr[i]];}return arr}
function missionStateLoad(){try{return JSON.parse(localStorage.getItem(MISSION_STATE_KEY)||"{}")}catch{return {}}}
function missionStateSave(v){localStorage.setItem(MISSION_STATE_KEY,JSON.stringify(v))}
function missionStageState(index,level){const all=missionStateLoad(),cur=all[String(index)];if(!cur||cur.level!==level){const fresh={level,stage:0,attempts:0,mistakes:0,run:cur?.run||0};all[String(index)]=fresh;missionStateSave(all);return fresh}return cur}
function saveMissionStageState(index,state){const all=missionStateLoad();all[String(index)]=state;missionStateSave(all)}

