const MASTERY_FLAVORS={
  tr:["süre kısıtlı.","kaynaklar sınırlı.","iki hedef aynı anda baskı oluşturuyor.","hata payı düşük.","geri dönüş seçeneği mevcut ama pahalı.","öncelikler çatışıyor.","bilgi eksik ve doğrulama gerekiyor.","beklenmeyen bir gecikme var.","başarı için sürdürülebilirlik önemli.","risk ile ödülü birlikte tartman gerekiyor.","ilk seçimin sonraki aşamayı etkiliyor.","tek bir plana bağımlı kalamazsın.","başkasının tercihi de sonucu değiştiriyor.","zamanlama doğru cevap kadar önemli.","küçük bir hata sonraki eşiği zorlaştırabilir.","önce kanıt, sonra karar gerekiyor."],
  en:["time is limited.","resources are limited.","two goals are creating pressure at once.","the margin for error is small.","a recovery option exists but is costly.","priorities are competing.","information is incomplete and needs verification.","an unexpected delay is present.","sustainability matters as much as speed.","you must weigh risk and reward together.","your first choice affects the next stage.","you cannot depend on a single plan.","someone else's preference also changes the outcome.","timing matters as much as the answer.","a small mistake can make the next gate harder.","evidence must come before the decision."]
};
function buildMasteryTrial(index,level,stage,run=0){
  const name=CHARACTERS[index][0],list=MASTERY_TEMPLATES[name]||MASTERY_TEMPLATES.KORA;
  const n=Math.abs(level*37 + stage*17 + run*997 + index*11);
  const raw=list[n%list.length](n);
  const diff=missionDifficulty(level);
  let options=[raw.correct,...raw.wrongs].slice(0,diff.options);
  while(options.length<diff.options) options.push(lang==="tr"?"Bu seçenek temel nedeni açıklamıyor.":"This option does not address the core reason.");
  const order=seededOrder(level*103+stage*47+run*19+index*13,options.length);
  const flavors=MASTERY_FLAVORS[lang==="en"?"en":"tr"];
  const flavor=flavors[(run+stage*3+index)%flavors.length];
  const variant=Math.floor(run/flavors.length)+1;
  const q=variant===1?`${raw.q} Bu turdaki koşul: ${flavor}`:`${raw.q} Bu turdaki koşul: ${flavor} Varyant ${variant}.`;
  return {question:q,options:order.map(i=>options[i]),answer:order.indexOf(0)};
}
function buildTrial(index,level,stage,state=null){
  if(level>100) return buildMasteryTrial(index,level,stage,state?.run||0);
  const name=CHARACTERS[index][0],bank=TRIAL_BANK[name]||TRIAL_BANK.KORA,raw=bank[(level*3+stage*5+index)%bank.length],diff=missionDifficulty(level),base=raw[1].slice(),decoys=lang==="tr"?["Bu seçenek sorunun temelini değiştirmiyor.","Bu yaklaşım sonucu değil, sadece görünüşü değiştirir.","Bu seçim için yeterli gerekçe yok."]:['This choice does not address the core of the question.','This approach changes appearance, not the actual decision.','There is not enough reasoning to support this choice.'];
  let options=base.slice();let d=0;while(options.length<diff.options){options.push(decoys[d%decoys.length]);d++;}
  const order=seededOrder(level*97+stage*31+index*11,options.length);return {question:raw[0],options:order.map(i=>options[i]),answer:order.indexOf(raw[2])};
}
function renderMissionChallenge(index,level,state){
  const box=$("#missionChallenge");if(!box)return;const diff=missionDifficulty(level);
  currentTrial=buildTrial(index,level,state.stage,state);selectedTrialChoice=null;
  const label=level>100?(lang==="tr"?"USTALIK+":"MASTERY+"):diff.name;
  const html=currentTrial.options.map((o,i)=>`<button type="button" class="challenge-option" data-choice="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join("");
  const intro=level>100?(lang==="tr"?"100 ana bölüm tamamlandı. Şimdi tekrar oynanabilir Ustalık+ sınavları yeni durumlarla gücünü test ediyor.":"The 100 main chapters are complete. Replayable Mastery+ trials now test your strength in changing situations."):"";
  box.innerHTML=`<span class="challenge-label">${label} · ${state.stage+1}/${diff.stages}</span>${intro?`<p class="mission-complete-note">${intro}</p>`:""}<p class="challenge-question">${currentTrial.question}</p><div class="challenge-options">${html}</div>`;
  $$(".challenge-option").forEach(b=>b.addEventListener("click",()=>{$$(".challenge-option").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");selectedTrialChoice=Number(b.dataset.choice);}));
}
function refreshMission(){
  const p=profile(),d=data();
  if(!p){$("#currentMissionLabel").textContent="01 / 100";$("#missionTitle").textContent=d.chapters[0][1];$("#missionDescription").textContent=lang==="tr"?"İlk adımını at.":"Take your first step.";$("#attemptCount").textContent="0";$("#attemptRequired").textContent="1";if($("#missionChallenge"))$("#missionChallenge").innerHTML="";return}
  if(p.character===null||p.character===undefined){$("#currentMissionLabel").textContent="— / 100";$("#missionTitle").textContent=lang==="tr"?"KARAKTERİNİ SEÇ":"CHOOSE YOUR CHARACTER";$("#missionDescription").textContent=lang==="tr"?"Kayıttan sonra karakterini seçtiğinde kişisel görevlerin açılacak.":"Choose your character after registration to unlock personal trials.";$("#attemptCount").textContent="0";$("#attemptRequired").textContent="—";if($("#missionChallenge"))$("#missionChallenge").innerHTML="";return}
  const i=p.character,progress=Math.min(p.progress?.[i]||0,100),level=progress+1,state=missionStageState(i,level),diff=missionDifficulty(level);currentMission=level;
  $("#currentMissionLabel").textContent=level>100?"MASTER / ∞":String(level).padStart(2,"0")+" / 100";
  $("#missionTitle").textContent=level===100?(lang==="tr"?"SON KAPI":"FINAL GATE"):(d.roles[i]+" — "+(lang==="tr"?"GÖREV":"TRIAL")+" "+level);
  $("#missionDescription").textContent=level>100?(lang==="tr"?"100 bölüm tamamlandı. Tekrar oynanabilir Ustalık+ görevleri devam ediyor.":"100 chapters complete. Replayable Mastery+ trials continue."):({tr:["Seçimini dikkatli yap. Her cevap sonraki eşiği etkiler.","İpucunu oku. Hız değil, doğru gerekçe ilerletir.","Bu bölüm birden fazla adım isteyebilir. Yaklaşımını değiştir."],en:["Choose carefully. Every answer affects the next gate.","Read the clue. Progress comes from reasoning, not speed.","This stage can require multiple steps. Change your approach."]}[lang]||[])[(level+state.stage)%3]||"Choose carefully.";
  $("#attemptCount").textContent=state.attempts||0;$("#attemptRequired").textContent=diff.stages;renderMissionChallenge(i,level,state);
}
function missionAttempt(){
  const p=profile();if(!p){showDialog("authDialog");return}if(p.character===null||p.character===undefined){openCharacterChooser();return}
  const i=p.character,progress=Math.min(p.progress?.[i]||0,100),level=progress+1;let state=missionStageState(i,level),diff=missionDifficulty(level);
  if(selectedTrialChoice===null){const box=$("#missionChallenge");if(box){box.style.boxShadow="0 0 0 1px rgba(216,174,99,.45) inset";setTimeout(()=>box.style.boxShadow="",420)}return}
  const buttons=$$(".challenge-option"),correct=selectedTrialChoice===currentTrial.answer;state.attempts=(state.attempts||0)+1;
  if(!correct){
    state.mistakes=(state.mistakes||0)+1;const chosen=buttons[selectedTrialChoice];if(chosen){chosen.classList.add("wrong");setTimeout(()=>chosen.classList.remove("wrong"),450)}saveMissionStageState(i,state);refreshMission();openChat(i);
    addChat("character",lang==="tr"?"Bu eşik henüz açılmadı. İpucunu yeniden oku; aynı cevabı tekrar etmek yerine düşünme biçimini değiştir.":"This gate stays closed. Re-read the clue; change your reasoning instead of repeating the same answer.");return;
  }
  const chosen=buttons[selectedTrialChoice];if(chosen)chosen.classList.add("correct");state.stage=(state.stage||0)+1;selectedTrialChoice=null;
  if(state.stage<diff.stages){state.mistakes=0;saveMissionStageState(i,state);refreshMission();openChat(i);addChat("character",lang==="tr"?"Doğru. Bir eşik daha var; acele etmeden devam et.":"Correct. One more gate remains; continue without rushing.");return}
  if(level>100){state.stage=0;state.attempts=0;state.mistakes=0;state.run=(state.run||0)+1;saveMissionStageState(i,state);refreshMission();openChat(i);addChat("character",lang==="tr"?"Ustalık+ sınavını tamamladın. Yeni sınav yeniden şekillendi; 100'den sonrası da yolculuğun bir parçası.":"Mastery+ trial complete. The next trial has been reshaped; the journey continues beyond 100.");return}
  p.progress=p.progress||Array(10).fill(0);p.progress[i]=Math.min(100,progress+1);saveProfile(p);attemptCount=0;saveMissionStageState(i,{level:progress+2,stage:0,attempts:0,mistakes:0});renderProfile();openChat(i);
  addChat("character",level===100?(lang==="tr"?"Son kapı açıldı. 100 bölüm tamamlandı — ama KORA burada bitmiyor. Ustalık+ artık açık ve daha zorlayıcı sınavlarla devam ediyor.":"The final gate opened. 100 chapters are complete — but KORA does not end here. Mastery+ is now open with harder replayable trials."):(lang==="tr"?"Bölüm tamamlandı. Yeni eşik daha fazlasını isteyecek.":"Chapter complete. The next gate will demand more from you."));
}

function renderIdeas(){
  const list=$("#communityIdeasList"); if(!list)return; 
  let ideas=[]; try{ideas=JSON.parse(localStorage.getItem(IDEAS_KEY)||"[]")}catch{ideas=[]}
  if(!ideas.length){
    list.innerHTML=`<div class="idea-item"><p>${lang==="tr"?"İlk fikri sen bırak.":"Be the first to share an idea."}</p></div>`; return;
  }
  list.innerHTML="";
  ideas.forEach((it,idx)=>{
    const row=document.createElement("div"); row.className="idea-item";
    row.innerHTML=`<p>${it.text}</p><button class="vote-btn">▲ ${it.votes||0}</button>`;
    row.querySelector("button").addEventListener("click",()=>{ideas[idx].votes=(ideas[idx].votes||0)+1;localStorage.setItem(IDEAS_KEY,JSON.stringify(ideas));renderIdeas();});
    list.appendChild(row);
  });
}

let authContactType = "email";
function setContactType(type){
  authContactType = type==="phone" ? "phone" : "email";
  $$(".contact-tab").forEach(t=>t.classList.toggle("active",t.dataset.contact===authContactType));
  const d=data();
  const label=$("#contactLabelText"), input=$("#authContact");
  if(authContactType==="phone"){
    label.textContent=d.phone || "PHONE";
    input.type="tel";
    input.autocomplete="tel";
    input.inputMode="tel";
    input.placeholder="+90 5XX XXX XX XX";
  }else{
    label.textContent=d.email || "EMAIL";
    input.type="email";
    input.autocomplete="email";
    input.inputMode="email";
    input.placeholder="you@example.com";
  }
}
function openAuth(mode="register"){
  const d=data();
  $("#authTitle").textContent = mode==="register" ? d.join : (lang==="tr"?"GİRİŞ YAP":"LOG IN");
  $("#authLead").textContent = mode==="register"
    ? (lang==="tr"?"Önce kayıt ol. Kayıttan sonra karakterini seç ve seçtiğin karakter seninle konuşmaya başlasın.":"Register first. After registration, choose your character and your character will begin talking to you.")
    : (lang==="tr"?"KORA profilini aç ve yolculuğuna devam et.":"Open your KORA profile and continue your journey.");
  $$(".tab").forEach(t=>t.classList.toggle("active",t.dataset.authTab===mode));
  $("#authSubmit").textContent=mode==="register"?(lang==="tr"?"PROFİL OLUŞTUR →":"CREATE PROFILE →"):(lang==="tr"?"GİRİŞ YAP →":"LOG IN →");
  $("#authName").style.display=mode==="register"?"block":"none";
  setContactType(authContactType);
  showDialog("authDialog");
}

function simpleHash(text){
  let h=2166136261;
  for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}
  return (h>>>0).toString(16);
}
async function hashSecret(text){
  try{
    if(window.crypto?.subtle){
      const buf=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(text));
      return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,"0")).join("");
    }
  }catch{}
  return simpleHash(text);
}
function normalizeContact(value,type){
  if(type==="phone") return value.replace(/\D/g,"");
  return value.trim().toLowerCase();
}
async function authSubmit(e){
  e.preventDefault();
  const name=$("#authName").value.trim();
  const contact=$("#authContact").value.trim();
  const password=$("#authPassword").value;
  const mode=$(".tab.active").dataset.authTab;
  if(mode==="register" && !name){$("#authName").focus();return}
  if(!contact || !password){$("#authContact").focus();return}
  if(password.length<6){alert(lang==="tr"?"Şifren en az 6 karakter olmalı.":"Password must be at least 6 characters.");return}
  if(authContactType==="phone"){
    const digits=contact.replace(/\D/g,"");
    if(digits.length<10 || digits.length>15){alert(lang==="tr"?"Geçerli bir telefon numarası gir.":"Enter a valid phone number.");return}
  }

  const existing=profile();
  const normalized=normalizeContact(contact,authContactType);
  const hash=await hashSecret(password);

  if(mode==="register"){
    const p={
      authVersion:AUTH_VERSION,registered:true,registeredAt:new Date().toISOString(),
      name,email:authContactType==="email"?normalized:"",phone:authContactType==="phone"?normalized:"",
      contactType:authContactType,passwordHash:hash,character:null,progress:Array(CHARACTERS.length).fill(0)
    };
    saveProfile(p);
    selectedCharacterIndex=null; closeDialog("authDialog"); renderProfile(); openCharacterChooser(); return;
  }

  // LOGIN NEVER CREATES AN ACCOUNT. It only accepts a previously registered v3 profile.
  if(!existing){
    alert(lang==="tr"?"Bu hesap kayıtlı değil. Önce KAYIT OL ile hesap oluşturmalısın.":"This account is not registered. Create your account with REGISTER first.");
    openAuth("register"); return;
  }
  const storedContact=normalizeContact(existing.contactType==="phone"?existing.phone:existing.email,existing.contactType||"email");
  if((existing.contactType||"email")!==authContactType || storedContact!==normalized || !existing.passwordHash || existing.passwordHash!==hash){
    alert(lang==="tr"?"E-posta/telefon veya şifre hatalı.":"Email/phone or password is incorrect.");
    return;
  }
  closeDialog("authDialog"); renderProfile();
  if(existing.character===null) openCharacterChooser(); else openChat(existing.character);
}

function sendSuggestion(e){
  e.preventDefault();
  let ideas=[]; try{ideas=JSON.parse(localStorage.getItem(IDEAS_KEY)||"[]")}catch{ideas=[]}
  ideas.unshift({text:$("#suggestionText").value.trim(),votes:0});
  localStorage.setItem(IDEAS_KEY,JSON.stringify(ideas)); $("#suggestionForm").reset(); closeDialog("suggestionDialog"); renderIdeas();
}

function supportReply(msg){
  const m=msg.toLowerCase();
  const set={
    en:m.includes("account")||m.includes("login")?"For account help, open Log In or Register. This prototype stores your profile in this browser.":"Tell me what you need help with. I can guide you to account, character, journey, support, or feedback features.",
    tr:m.includes("hesap")||m.includes("giriş")?"Hesap için Giriş Yap veya Kayıt Ol alanını kullan. Bu prototip profilini bu tarayıcıda saklar.":"Ne konuda yardıma ihtiyacın var? Hesap, karakter, yolculuk, destek veya öneri alanlarına yönlendirebilirim.",
    de:"Ich kann dich zu Konto, Charakter, Reise, Support oder Feedback führen.",
    fr:"Je peux te guider vers le compte, le personnage, le voyage, l'assistance ou les idées.",
    es:"Puedo ayudarte con la cuenta, el personaje, el viaje, el soporte o las ideas.",
    it:"Posso guidarti tra account, personaggio, viaggio, supporto e idee."
  };
  return set[lang]||set.en;
}

document.addEventListener("DOMContentLoaded",()=>{
  $("#languageSelect").addEventListener("change",e=>applyLanguage(e.target.value));
  $("#registerButton").addEventListener("click",()=>openAuth("register"));
  $("#loginButton").addEventListener("click",()=>openAuth("login"));
  $("#headerProfile").addEventListener("click",()=>{
    const p=profile();
    if(!p) return openAuth("register");
    document.querySelector("#profile")?.scrollIntoView({behavior:"smooth",block:"start"});
  });
  // New journey always begins with registration. Character selection comes after account creation.
  $("#startJourney").addEventListener("click",()=>profile()?openCharacterChooser():openAuth("register"));
  $("#finalStartBtn").addEventListener("click",()=>profile()?openCharacterChooser():openAuth("register"));
  $("#chooseCharacterBtn").addEventListener("click",()=>profile()?openCharacterChooser():openAuth("register"));
  $("#changeCharacterBtn").addEventListener("click",()=>openCharacterChooser());
  $("#tryMissionBtn").addEventListener("click",missionAttempt);
  $("#confirmCharacter").addEventListener("click",()=>{
    const button=$("#confirmCharacter");
    const chosen=Number.isInteger(selectedCharacterIndex) ? selectedCharacterIndex : Number(button.dataset.selectedCharacter);
    if(Number.isInteger(chosen) && CHARACTERS[chosen]) {
      selectCharacter(chosen,true);
      return;
    }
    const notice=lang==="tr" ? "Önce bir karakter seç." : "Choose a character first.";
    addChat("character",notice);
  });
  $$("[data-close]").forEach(b=>b.addEventListener("click",()=>closeDialog(b.dataset.close)));
  $$(".tab").forEach(t=>t.addEventListener("click",()=>openAuth(t.dataset.authTab)));
  $$(".contact-tab").forEach(t=>t.addEventListener("click",()=>setContactType(t.dataset.contact)));
  $("#authForm").addEventListener("submit",authSubmit);
  $("#suggestionBtn").addEventListener("click",()=>showDialog("suggestionDialog"));
  $("#supportBtn").addEventListener("click",()=>{
    $("#supportMessages").innerHTML="";
    const welcome={en:"Hello. I’m KORA AI Support. How can I help?",tr:"Merhaba. Ben KORA AI Destek. Nasıl yardımcı olabilirim?",de:"Hallo. Ich bin KORA KI-Support. Wie kann ich helfen?",fr:"Bonjour. Je suis KORA Support IA. Comment puis-je aider ?",es:"Hola. Soy Soporte IA de KORA. ¿Cómo puedo ayudarte?",it:"Ciao. Sono KORA Supporto IA. Come posso aiutarti?"}[lang]||"Hello. How can I help?";
    const div=document.createElement("div");div.className="msg character";div.textContent=welcome;$("#supportMessages").appendChild(div);
    showDialog("supportDialog");
  });
  $("#suggestionForm").addEventListener("submit",sendSuggestion);
  $("#chatForm").addEventListener("submit",e=>{
    e.preventDefault(); const msg=$("#chatInput").value.trim(); if(!msg)return;
    const i=profile()?.character??0; addChat("user",msg); $("#chatInput").value="";
    setTimeout(()=>{
      const reply=characterReply(i,msg);
      addChat("character",reply);
      rememberTurn(i,msg,reply);
    },160);
  });
  $("#supportForm").addEventListener("submit",e=>{
    e.preventDefault(); const msg=$("#supportInput").value.trim(); if(!msg)return;
    const wrap=document.createElement("div");wrap.className="msg user";wrap.textContent=msg;$("#supportMessages").appendChild(wrap);$("#supportInput").value="";
    setTimeout(()=>{const r=document.createElement("div");r.className="msg character";r.textContent=supportReply(msg);$("#supportMessages").appendChild(r);$("#supportMessages").scrollTop=$("#supportMessages").scrollHeight},160);
  });
  $$("[data-open-discovery]").forEach(b=>b.addEventListener("click",()=>openDiscovery(["universe","worlds"].indexOf(b.dataset.openDiscovery)==0?0:4)));
  applyLanguage("en");
});
